import{_ as d,o as a,c as i,a3 as r}from"./chunks/framework.Q4yG9rk_.js";const s=JSON.parse('{"title":"荀子","description":"《荀子》三十二篇的原文与逐篇导读：从劝学、修身进入礼义、天人、心知与性伪之辨。","frontmatter":{"title":"荀子","description":"《荀子》三十二篇的原文与逐篇导读：从劝学、修身进入礼义、天人、心知与性伪之辨。","category":"guide","aliases":["荀子","荀子目录","荀卿","xunzi"],"source":["维基文库《荀子》三十二篇电子录文"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/xunzi/index.md","filePath":"lizhimingde/xunzi/index.md","lastUpdated":1794362429000}'),e={name:"lizhimingde/xunzi/index.md"};function h(n,t,o,l,z,u){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="荀子" tabindex="-1">荀子 <a class="header-anchor" href="#荀子" aria-label="Permalink to &quot;荀子&quot;">​</a></h1><p>《荀子》是战国后期儒家思想的重要典籍，今传 <strong>三十二篇</strong>，主要保存荀况及其学派的论说。它把学习、师法、礼义与制度放在显著位置，追问一个人如何经由后天的学习和实践成就德行，又如何与他人共同生活。</p><p>本站将它单列在「立志明德」之下，与<a href="/Dao/lizhimingde/sishu-wujing/">四书五经</a>并列；《荀子》属于先秦儒家重要著作，并非四书五经中的一部。</p><h2 id="为什么读" tabindex="-1">为什么读 <a class="header-anchor" href="#为什么读" aria-label="Permalink to &quot;为什么读&quot;">​</a></h2><p>读过<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a>的修身次第、<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a>的心性工夫，再读《荀子》，可以继续追问：德行怎样练成，欲望怎样得到合宜安排，礼义与制度为什么必要，人的认识又如何避免偏蔽。</p><p>不必用「性恶」两个字概括全书。先看《劝学》《修身》中的学习过程，再连读《天论》《解蔽》《正名》《性恶》，会更容易看清各个命题的关系。</p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li><strong>从学习与修身进入</strong>：顺读《劝学》《修身》《不苟》《荣辱》，先抓住个人实践的问题。</li><li><strong>再看礼义怎样组织共同生活</strong>：选读《王制》《富国》《礼论》《乐论》，把个人修养与制度安排连接起来。</li><li><strong>随后辨概念和论证</strong>：读《天论》《解蔽》《正名》《性恶》，留意天与人、心与蔽、名与实、性与伪的区分。「伪」在相关语境中指人为的学习与作为，不宜直接当作虚伪。</li><li><strong>最后回看短章与故事</strong>：《大略》《宥坐》等篇可与前面的论说互证，但不把全书每篇都视为同一场合的一次发言。</li></ol><p>也可以按下面的通行篇次，从第一篇依次读下去。</p><h2 id="整理方式与进度" tabindex="-1">整理方式与进度 <a class="header-anchor" href="#整理方式与进度" aria-label="Permalink to &quot;整理方式与进度&quot;">​</a></h2><p>沿用《大学》《中庸》的分层阅读体例：<strong>一篇一页，篇内按段阅读；原文 → 字词点查 → 白话译文 → 三问解读 → 现代重述 → 个人笔记</strong>。</p><ul><li><strong>原文层：32/32 篇已录入</strong>，取维基文库简体显示的全篇正文，分离夹注，逐篇标出所据修订版；不是课本节选。</li><li><strong>释义与解读层：1/32 篇完成首轮整理</strong>，首篇《劝学》分为十六个阅读段，已补段级白话、字词和三问，待作者审读。</li><li><strong>其余31篇</strong>先供原文通读，后续按篇补入释义和解读。原文录入不等于全书精读整理完成。</li><li>个人笔记保持留白，原文、本站释义与个人理解分层呈现。</li></ul><p>从<a href="/Dao/lizhimingde/xunzi/chapter-01">第1篇·劝学</a>开始。下一篇精读：《修身》。</p><h2 id="篇目目录" tabindex="-1">篇目目录 <a class="header-anchor" href="#篇目目录" aria-label="Permalink to &quot;篇目目录&quot;">​</a></h2><p>下列主题为本站导读概括；篇次沿用今传三十二篇的通行顺序，不按主题重新编排。</p><table tabindex="0"><thead><tr><th>序</th><th>篇名</th><th>本篇关注</th><th>当前进度</th></tr></thead><tbody><tr><td>01</td><td><a href="/Dao/lizhimingde/xunzi/chapter-01">劝学</a></td><td>学习如何改变人，怎样积累、专一并落实于行为</td><td>首轮整理</td></tr><tr><td>02</td><td><a href="/Dao/lizhimingde/xunzi/chapter-02">修身</a></td><td>以自省、师友与礼义修养身心</td><td>原文已录入</td></tr><tr><td>03</td><td><a href="/Dao/lizhimingde/xunzi/chapter-03">不苟</a></td><td>辨别君子的持守与苟且取容</td><td>原文已录入</td></tr><tr><td>04</td><td><a href="/Dao/lizhimingde/xunzi/chapter-04">荣辱</a></td><td>从欲望、行为与处境辨荣辱的来由</td><td>原文已录入</td></tr><tr><td>05</td><td><a href="/Dao/lizhimingde/xunzi/chapter-05">非相</a></td><td>反对凭相貌判断人的德行与才智</td><td>原文已录入</td></tr><tr><td>06</td><td><a href="/Dao/lizhimingde/xunzi/chapter-06">非十二子</a></td><td>批评诸家学说，申明所持的儒学立场</td><td>原文已录入</td></tr><tr><td>07</td><td><a href="/Dao/lizhimingde/xunzi/chapter-07">仲尼</a></td><td>借孔子与弟子论为人、为臣和处世</td><td>原文已录入</td></tr><tr><td>08</td><td><a href="/Dao/lizhimingde/xunzi/chapter-08">儒效</a></td><td>讨论儒者的学习、能力与政治作用</td><td>原文已录入</td></tr><tr><td>09</td><td><a href="/Dao/lizhimingde/xunzi/chapter-09">王制</a></td><td>讨论礼义、分工与治理的制度安排</td><td>原文已录入</td></tr><tr><td>10</td><td><a href="/Dao/lizhimingde/xunzi/chapter-10">富国</a></td><td>从生产、节用与制度讨论富国之道</td><td>原文已录入</td></tr><tr><td>11</td><td><a href="/Dao/lizhimingde/xunzi/chapter-11">王霸</a></td><td>辨别王道、霸道及其得失</td><td>原文已录入</td></tr><tr><td>12</td><td><a href="/Dao/lizhimingde/xunzi/chapter-12">君道</a></td><td>讨论君主用人、听政与治国的责任</td><td>原文已录入</td></tr><tr><td>13</td><td><a href="/Dao/lizhimingde/xunzi/chapter-13">臣道</a></td><td>辨别臣子的职责、忠顺与谏争</td><td>原文已录入</td></tr><tr><td>14</td><td><a href="/Dao/lizhimingde/xunzi/chapter-14">致士</a></td><td>讨论招致、任用与安顿贤士</td><td>原文已录入</td></tr><tr><td>15</td><td><a href="/Dao/lizhimingde/xunzi/chapter-15">议兵</a></td><td>将用兵放回仁义、民心与政治秩序中</td><td>原文已录入</td></tr><tr><td>16</td><td><a href="/Dao/lizhimingde/xunzi/chapter-16">强国</a></td><td>讨论国家强盛的条件与秦国的得失</td><td>原文已录入</td></tr><tr><td>17</td><td><a href="/Dao/lizhimingde/xunzi/chapter-17">天论</a></td><td>区分天的运行与人的治理责任</td><td>原文已录入</td></tr><tr><td>18</td><td><a href="/Dao/lizhimingde/xunzi/chapter-18">正论</a></td><td>辨正有关古今政治与制度的议论</td><td>原文已录入</td></tr><tr><td>19</td><td><a href="/Dao/lizhimingde/xunzi/chapter-19">礼论</a></td><td>追问礼的起源、功能与节度</td><td>原文已录入</td></tr><tr><td>20</td><td><a href="/Dao/lizhimingde/xunzi/chapter-20">乐论</a></td><td>说明礼乐如何调节情感、协调群体</td><td>原文已录入</td></tr><tr><td>21</td><td><a href="/Dao/lizhimingde/xunzi/chapter-21">解蔽</a></td><td>辨识认识中的偏蔽，讨论心如何知与择</td><td>原文已录入</td></tr><tr><td>22</td><td><a href="/Dao/lizhimingde/xunzi/chapter-22">正名</a></td><td>讨论名称、实物、约定与言说秩序</td><td>原文已录入</td></tr><tr><td>23</td><td><a href="/Dao/lizhimingde/xunzi/chapter-23">性恶</a></td><td>辨性与伪，讨论学习和礼义如何成就善</td><td>原文已录入</td></tr><tr><td>24</td><td><a href="/Dao/lizhimingde/xunzi/chapter-24">君子</a></td><td>讨论君子在不同处境中的持守与作用</td><td>原文已录入</td></tr><tr><td>25</td><td><a href="/Dao/lizhimingde/xunzi/chapter-25">成相</a></td><td>以韵文议论治乱、用人与历史得失</td><td>原文已录入</td></tr><tr><td>26</td><td><a href="/Dao/lizhimingde/xunzi/chapter-26">赋</a></td><td>以隐语问答与韵文铺陈礼、知等主题</td><td>原文已录入</td></tr><tr><td>27</td><td><a href="/Dao/lizhimingde/xunzi/chapter-27">大略</a></td><td>汇集礼义、为学与处世的短章杂论</td><td>原文已录入</td></tr><tr><td>28</td><td><a href="/Dao/lizhimingde/xunzi/chapter-28">宥坐</a></td><td>借孔子故事讨论持满、修身与进退</td><td>原文已录入</td></tr><tr><td>29</td><td><a href="/Dao/lizhimingde/xunzi/chapter-29">子道</a></td><td>讨论为子、为弟子之道及孝的分寸</td><td>原文已录入</td></tr><tr><td>30</td><td><a href="/Dao/lizhimingde/xunzi/chapter-30">法行</a></td><td>借言行故事呈现礼义的具体实践</td><td>原文已录入</td></tr><tr><td>31</td><td><a href="/Dao/lizhimingde/xunzi/chapter-31">哀公</a></td><td>借鲁哀公问答讨论政治与识人</td><td>原文已录入</td></tr><tr><td>32</td><td><a href="/Dao/lizhimingde/xunzi/chapter-32">尧问</a></td><td>以问答和轶事收束治道、处世与人物评论</td><td>原文已录入</td></tr></tbody></table><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>阅读入口</th><th>先辨什么</th></tr></thead><tbody><tr><td>学与积</td><td>劝学、修身</td><td>学习不止于口耳，积累要贯通到行为</td></tr><tr><td>礼与分</td><td>王制、礼论</td><td>礼既关乎行为节度，也关乎共同生活的安排</td></tr><tr><td>天与人</td><td>天论</td><td>天的运行与人的治理责任如何区分</td></tr><tr><td>心与蔽</td><td>解蔽</td><td>为什么片面的看见可能遮蔽整体判断</td></tr><tr><td>名与实</td><td>正名</td><td>命名、约定与辨别事物如何相连</td></tr><tr><td>性与伪</td><td>性恶</td><td>天生的禀性与后天的学习、作为如何区别</td></tr></tbody></table><h2 id="来源与整理说明" tabindex="-1">来源与整理说明 <a class="header-anchor" href="#来源与整理说明" aria-label="Permalink to &quot;来源与整理说明&quot;">​</a></h2><p>原文入口：<a href="https://zh.wikisource.org/wiki/%E8%8D%80%E5%AD%90" target="_blank" rel="noreferrer">维基文库《荀子》</a>。已逐篇取得从《劝学》至《尧问》的32篇电子录文；所据页面附有古注，本站仅取正文，各篇页末保留具体来源与固定修订版链接。访问日期：2026-11-10。</p><p>本站沿用该电子录文的简体显示，不额外将异体字统一成课本字形，也不拼入其他版本的字句。篇题「强国」的来源写作「彊國篇」，已在对应页说明。原文录入与结构核对，不能替代影印逐字校勘；后续发现异文会另作说明。</p><p>白话和解读为本站重述，参考线索逐篇标注，不搬运现代译注。</p><h2 id="我的笔记" tabindex="-1">我的笔记 <a class="header-anchor" href="#我的笔记" aria-label="Permalink to &quot;我的笔记&quot;">​</a></h2><blockquote><p>读过一篇，再记录自己赞同、存疑与准备尝试的地方。</p></blockquote><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/">立志明德</a></li><li>对读：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>道家对读：<a href="/Dao/daoism/zhuang-zi/">庄子</a></li></ul>',26)])])}const p=d(e,[["render",h]]);export{s as __pageData,p as default};
